export const provisioningStatus = pgEnum("provisioning_status", ["pending", "running", "completed", "failed", "retrying"]);
export const planCode = pgEnum("plan_code", ["FREE", "STARTER", "PROFESSIONAL", "ENTERPRISE"]);
export const masterDataStatus = pgEnum("master_data_status", ["active", "inactive"]);
export const employeeStatus = pgEnum("employee_status", ["invited", "onboarding", "active", "probation", "confirmed", "notice_period", "inactive", "resigned", "terminated", "exited"]);
export const onboardingStatus = pgEnum("onboarding_status", ["not_started", "invited", "in_progress", "completed", "blocked"]);
export const onboardingItemStatus = pgEnum("onboarding_item_status", ["pending", "completed", "blocked"]);
export const documentStatus = pgEnum("document_status", ["pending", "verified", "rejected", "expired"]);
