export const regularizationStatus = pgEnum("regularization_status", ["pending", "approved", "rejected", "cancelled"]);
export const leaveApplicationStatus = pgEnum("leave_application_status", ["draft", "pending", "approved", "rejected", "cancelled", "withdrawn"]);
export const leaveTransactionType = pgEnum("leave_transaction_type", ["opening", "accrual", "consumption", "reservation", "reservation_release", "cancellation_reversal", "adjustment", "carry_forward", "expiry"]);
export const workflowStatus = pgEnum("workflow_status", ["pending", "in_progress", "approved", "rejected", "cancelled", "failed"]);
export const workflowStepMode = pgEnum("workflow_step_mode", ["sequential", "parallel"]);
